use std::sync::{Arc, Mutex};
use std::time::Duration;

use grow_signoz as sdk;
use sdk::logging::{
    connect_log_client, current_request_id, init_logging, with_request_id, Attributes,
    BatchOptions, BatchingLogClient, InitOptions, LogConnection, LogConnector, LogEntry, LogInput,
    LogRecord, Severity, LOG_SHIPPED_FIELD,
};
use sdk::testing::logging::MemoryLogExporter;
