fn capture() -> (Arc<Mutex<Vec<String>>>, sdk::logging::LineWriter) {
    let lines = Arc::new(Mutex::new(Vec::new()));
    let sink = lines.clone();
    (
        lines,
        Arc::new(move |l: &str| sink.lock().unwrap().push(l.to_string())),
    )
}

fn parsed(lines: &Arc<Mutex<Vec<String>>>) -> Vec<Value> {
    lines
        .lock()
        .unwrap()
        .iter()
        .map(|l| serde_json::from_str(l).unwrap())
        .collect()
}

fn env(pairs: &[(&str, &str)]) -> Option<HashMap<String, String>> {
    Some(
        pairs
            .iter()
            .map(|(k, v)| (k.to_string(), v.to_string()))
            .collect(),
    )
}

fn memory_connector(exporter: MemoryLogExporter, retries: u32) -> LogConnector {
    Arc::new(move |resource, _env, on_dropped| {
        let opts = BatchOptions {
            on_drop: Some(on_dropped),
            max_export_retries: retries,
            flush_interval: Duration::from_secs(60),
            ..BatchOptions::default()
        };
        let client = BatchingLogClient::builder(Arc::new(exporter.clone()))
            .batch_options(opts)
            .resource(resource.clone())
            .build()?;
        Ok(Some(LogConnection {
            logs: Arc::new(client),
        }))
    })
}

#[tokio::test]
async fn stdout_only() {
    let (lines, writer) = capture();
    let h = init_logging(InitOptions {
        env: env(&[
            ("GROW_SERVICE_NAME", "orders"),
            ("GROW_ENVIRONMENT", "dev"),
            ("LOG_LEVEL", "debug"),
        ]),
        writer: Some(writer),
        ..InitOptions::default()
    });
    assert!(!h.shipped());
    assert_eq!(h.service(), "orders");
    let logger = h.logger();
    with_request_id("req-1", async {
        assert_eq!(current_request_id().as_deref(), Some("req-1"));
        let mut a = Attributes::new();
        a.insert("password".into(), "p".into());
        logger.log(Severity::Debug, "hello", a);
    })
    .await;
    logger.log(Severity::Trace, "hidden", Attributes::new());
    let out = parsed(&lines);
    assert_eq!(out.len(), 1);
    assert_eq!(out[0]["level"], "debug");
    assert_eq!(out[0]["environment"], "dev");
    assert_eq!(out[0]["password"], "[REDACTED]");
    assert_eq!(out[0]["request_id"], "req-1");
    assert!(out[0].get(LOG_SHIPPED_FIELD).is_none());
    assert!(!h.canary("c", Attributes::new()).await);
    h.flush().await.unwrap();
    h.close().await.unwrap();
    assert!(format!("{h:?}").contains("orders"));
    assert_eq!(h.client().stats().sent, 0);
    assert!(format!("{:?}", InitOptions::default()).contains("stdout: true"));
}

#[tokio::test]
async fn ships_canary_and_reemits_failures() {
    let exporter = MemoryLogExporter::new();
    let (lines, writer) = capture();
    let h = init_logging(InitOptions {
        service: Some("svc".into()),
        level: Some("info".into()),
        env: env(&[("GROW_LOGGING_PROVIDER", "signoz")]),
        writer: Some(writer),
        connector: Some(memory_connector(exporter.clone(), 0)),
        ..InitOptions::default()
    });
    assert!(h.shipped());
    let mut a = Attributes::new();
    a.insert("token".into(), "t".into());
    h.logger().log(Severity::Info, "shipped", a);
    assert!(h.canary("foundation-canary-1", Attributes::new()).await);
    h.client().send(LogEntry::Record(
        LogRecord::new(Severity::Warn, "raw").with_trace("0".repeat(32), "1".repeat(16)),
    ));
    exporter.fail_next(Error::unavailable("down"));
    h.logger().log(Severity::Error, "lost", Attributes::new());
    h.flush().await.unwrap();
    h.close().await.unwrap();
    h.close().await.unwrap();
    let out = parsed(&lines);
    assert_eq!(out[0][LOG_SHIPPED_FIELD], "sdk");
    assert_eq!(out[0]["token"], "[REDACTED]");
    let failed: Vec<&Value> = out
        .iter()
        .filter(|l| l[LOG_SHIPPED_FIELD] == "sdk_failed")
        .collect();
    assert!(!failed.is_empty());
    assert!(failed
        .iter()
        .any(|l| l["msg"] == "lost" && l["service"] == "svc"));
    let bodies: Vec<String> = exporter.records().into_iter().map(|r| r.body).collect();
    assert!(bodies.contains(&"shipped".to_string()));
    assert!(bodies.contains(&"foundation-canary-1".to_string()));
}

#[tokio::test]
async fn connector_failure_default_connector_and_no_stdout() {
    let (lines, writer) = capture();
    let failing: LogConnector = Arc::new(|_r, _e, _d| Err(Error::config("boom")));
    let h = init_logging(InitOptions {
        ship: Some(true),
        stdout: false,
        env: env(&[]),
        writer: Some(writer.clone()),
        connector: Some(failing),
        ..InitOptions::default()
    });
    h.logger()
        .log(Severity::Info, "not written", Attributes::new());
    let out = parsed(&lines);
    assert_eq!(out.len(), 1);
    assert_eq!(out[0]["level"], "warn");
    assert_eq!(h.service(), "unknown_service");
    let d = init_logging(InitOptions {
        ship: Some(true),
        env: env(&[]),
        writer: Some(writer),
        ..InitOptions::default()
    });
    d.close().await.unwrap();
    let noop: sdk::logging::DropCallback = Arc::new(|_r, _reason| {});
    if let Some(conn) = connect_log_client(&Attributes::new(), &HashMap::new(), noop).unwrap() {
        conn.logs.close().await.unwrap();
    }
    let input = LogInput::new("x");
    h.client().send(LogEntry::Input(input));
    let _ = h.client().logger(None, Attributes::new());
}
